arguments.command:
python3 - <<'PY'
import importlib.util, sys, subprocess
mods={'pandas':'pandas','openpyxl':'openpyxl','python-docx':'docx'}
missing=[pkg for pkg,mod in mods.items() if importlib.util.find_spec(mod) is None]
if missing:
    print('Installing missing packages:', missing)
    subprocess.check_call([sys.executable, '-m', 'pip', 'install', '--break-system-packages', *missing])
else:
    print('All required packages already installed: pandas, openpyxl, python-docx')
PY
